<template><n-config-provider :theme="mode==='dark'?darkTheme:null" :theme-overrides="theme" :locale="zhCN" :date-locale="dateZhCN"><n-message-provider><router-view /></n-message-provider></n-config-provider></template>
<script setup lang="ts">
import{computed,provide,ref,watch}from'vue'
import{darkTheme,dateZhCN,zhCN,type GlobalThemeOverrides}from'naive-ui'
import{themeKey,type ThemeMode}from'./composables/theme'
const stored=localStorage.getItem('flood-risk-theme')
// 默认使用浅色科研工作台主题；仅在用户显式保存 dark 时启用深色主题。
const mode=ref<ThemeMode>(stored==='dark'?'dark':'light')
const toggle=()=>{mode.value=mode.value==='dark'?'light':'dark'}
watch(mode,value=>{localStorage.setItem('flood-risk-theme',value);document.documentElement.classList.toggle('theme-light',value==='light')},{immediate:true})
provide(themeKey,{mode,toggle})
const dark:GlobalThemeOverrides={common:{bodyColor:'#111827',cardColor:'#18212F',modalColor:'#18212F',popoverColor:'#18212F',primaryColor:'#4F8FEF',primaryColorHover:'#6DA2F2',primaryColorPressed:'#3976CF',infoColor:'#4F8FEF',successColor:'#4D9A72',warningColor:'#C58A32',errorColor:'#D05C65',textColorBase:'#E5E7EB',textColor1:'#F3F4F6',textColor2:'#CBD5E1',textColor3:'#94A3B8',borderColor:'#334155',dividerColor:'#334155',borderRadius:'6px'},Card:{color:'#18212F',borderColor:'#334155',borderRadius:'6px'},Button:{borderRadiusMedium:'5px',borderRadiusSmall:'4px'},DataTable:{thColor:'#202B3A',thColorHover:'#263446',tdColor:'#18212F',tdColorHover:'#202B3A',borderColor:'#334155'},Menu:{itemColorActive:'#243654',itemColorActiveHover:'#293D5E',itemTextColorActive:'#8CB7F5',itemIconColorActive:'#8CB7F5'},Tag:{borderRadius:'4px'}}
const light:GlobalThemeOverrides={common:{bodyColor:'#F5F7FA',cardColor:'#FFFFFF',modalColor:'#FFFFFF',popoverColor:'#FFFFFF',primaryColor:'#2563EB',primaryColorHover:'#1D4ED8',primaryColorPressed:'#1E40AF',primaryColorSuppl:'#3B82F6',infoColor:'#2563EB',successColor:'#3F8A63',warningColor:'#B7791F',errorColor:'#C2414B',textColorBase:'#1F2937',textColor1:'#1F2937',textColor2:'#667085',textColor3:'#98A2B3',borderColor:'#E5E7EB',dividerColor:'#E5E7EB',borderRadius:'6px',boxShadow1:'none',boxShadow2:'none',boxShadow3:'none'},Card:{color:'#FFFFFF',borderColor:'#E5E7EB',borderRadius:'6px',titleTextColor:'#1F2937'},Button:{borderRadiusMedium:'5px',borderRadiusSmall:'4px',textColorPrimary:'#FFFFFF',textColorHoverPrimary:'#FFFFFF',textColorPressedPrimary:'#FFFFFF',colorPrimary:'#2563EB',colorHoverPrimary:'#1D4ED8',colorPressedPrimary:'#1E40AF',color:'#FFFFFF',colorHover:'#F8FAFC',colorPressed:'#F1F5F9',border:'1px solid #D0D5DD',borderHover:'1px solid #98A2B3',borderPressed:'1px solid #667085',textColor:'#344054',textColorHover:'#1F2937'},DataTable:{thColor:'#F8FAFC',thColorHover:'#F1F5F9',tdColor:'#FFFFFF',tdColorHover:'#F8FAFC',borderColor:'#E5E7EB',thTextColor:'#475467',tdTextColor:'#344054'},Menu:{itemColorActive:'#EFF6FF',itemColorActiveHover:'#E8F1FF',itemTextColorActive:'#1D4ED8',itemIconColorActive:'#2563EB',itemColorHover:'#F8FAFC',itemTextColor:'#475467',itemIconColor:'#667085'},Input:{color:'#FFFFFF',colorFocus:'#FFFFFF',border:'1px solid #D0D5DD',borderHover:'1px solid #98A2B3',borderFocus:'1px solid #2563EB',boxShadowFocus:'0 0 0 2px rgba(37,99,235,.08)',placeholderColor:'#98A2B3',textColor:'#1F2937'},Select:{color:'#FFFFFF',colorFocus:'#FFFFFF',border:'1px solid #D0D5DD',borderHover:'1px solid #98A2B3',borderFocus:'1px solid #2563EB',boxShadowFocus:'0 0 0 2px rgba(37,99,235,.08)',placeholderColor:'#98A2B3',textColor:'#1F2937'},Tag:{borderRadius:'4px'}}
const theme=computed(()=>mode.value==='dark'?dark:light)
</script>
